(function() {
'use strict';
if (window.__vighnaghnaInitialized || window.__botFenceInitialized) {
return;
}
window.__vighnaghnaInitialized = true;
window.__botFenceInitialized = true;
window.__klAntiSpamInitialized = true;
var config = window.vighnaghnaSettings || window.botfenceSettings || window.klAntiSpamSettings || {
restUrl: '/wp-json/vighnaghna/v1/',
ajaxUrl: '/wp-admin/admin-ajax.php',
nonce: '',
tokenLifetime: 600,
minTime: 2.5
};
var pageLoadTime = Date.now();
var firstInteractionTime = null;
var mouseMoves = 0;
var keystrokes = 0;
var touchEvents = 0;
var focusEvents = 0;
var pasteCount = 0;
var autofillDetected = false;
var lastMouseMove = 0;
function recordFirstInteraction() {
if (firstInteractionTime === null) {
firstInteractionTime = Date.now();
}
}
window.addEventListener('mousemove', function() {
recordFirstInteraction();
var now = Date.now();
if (now - lastMouseMove > 50) {
mouseMoves++;
lastMouseMove = now;
}
}, { passive: true });
window.addEventListener('keydown', function() {
recordFirstInteraction();
keystrokes++;
}, { passive: true });
window.addEventListener('touchstart', function() {
recordFirstInteraction();
touchEvents++;
}, { passive: true });
window.addEventListener('focusin', function() {
recordFirstInteraction();
focusEvents++;
}, { passive: true });
window.addEventListener('paste', function() {
recordFirstInteraction();
pasteCount++;
}, { passive: true });
window.addEventListener('change', function(e) {
recordFirstInteraction();
if (e.target && (e.target.matches && e.target.matches(':-webkit-autofill') || e.target.getAttribute('autocomplete'))) {
autofillDetected = true;
}
}, { passive: true });
function safeBtoa(str) {
try {
return window.btoa(unescape(encodeURIComponent(str)));
} catch (e) {
return '';
}
}
function collectTelemetry(e) {
var now = Date.now();
var start = firstInteractionTime !== null ? firstInteractionTime : pageLoadTime;
var elapsed = Math.max(0.01, (now - start) / 1000);
var data = {
elapsed_time: parseFloat(elapsed.toFixed(3)),
mouse_moves: mouseMoves,
keystrokes: keystrokes,
touches: touchEvents,
focus_count: focusEvents,
paste_count: pasteCount,
autofill: autofillDetected,
is_trusted: e && typeof e.isTrusted !== 'undefined' ? !!e.isTrusted : true,
webdriver: !!(navigator.webdriver || window._phantom || window.__nightmare),
screen_dim: [window.screen ? window.screen.width : 0, window.screen ? window.screen.height : 0]
};
return safeBtoa(JSON.stringify(data));
}
function prepareForm(form) {
if (!form || form.nodeName !== 'FORM') return;
var tokenInput = form.querySelector('input.vighnaghna-token, input[name="vighnaghna_token"]');
if (!tokenInput) {
tokenInput = document.createElement('input');
tokenInput.type = 'hidden';
tokenInput.name = 'vighnaghna_token';
tokenInput.className = 'vighnaghna-token botfence-token kl-anti-spam-token';
form.appendChild(tokenInput);
}
var legacyToken = form.querySelector('input[name="botfence_token"]');
if (!legacyToken) {
legacyToken = document.createElement('input');
legacyToken.type = 'hidden';
legacyToken.name = 'botfence_token';
legacyToken.className = 'botfence-token';
form.appendChild(legacyToken);
}
var klToken = form.querySelector('input[name="kl_anti_spam_token"]');
if (!klToken) {
klToken = document.createElement('input');
klToken.type = 'hidden';
klToken.name = 'kl_anti_spam_token';
klToken.className = 'kl-anti-spam-token';
form.appendChild(klToken);
}
var telemetryInput = form.querySelector('input.vighnaghna-telemetry, input[name="vighnaghna_telemetry"]');
if (!telemetryInput) {
telemetryInput = document.createElement('input');
telemetryInput.type = 'hidden';
telemetryInput.name = 'vighnaghna_telemetry';
telemetryInput.className = 'vighnaghna-telemetry botfence-telemetry kl-anti-spam-telemetry';
form.appendChild(telemetryInput);
}
var legacyTelemetry = form.querySelector('input[name="botfence_telemetry"]');
if (!legacyTelemetry) {
legacyTelemetry = document.createElement('input');
legacyTelemetry.type = 'hidden';
legacyTelemetry.name = 'botfence_telemetry';
form.appendChild(legacyTelemetry);
}
var klTelemetry = form.querySelector('input[name="kl_anti_spam_telemetry"]');
if (!klTelemetry) {
klTelemetry = document.createElement('input');
klTelemetry.type = 'hidden';
klTelemetry.name = 'kl_anti_spam_telemetry';
form.appendChild(klTelemetry);
}
}
function attachFormSubmitHandler(form) {
if (!form || form.__vighnaghnaProtected) return;
form.__vighnaghnaProtected = true;
form.__botFenceProtected = true;
form.__klProtected = true;
prepareForm(form);
form.addEventListener('submit', function(e) {
var telemetryVal = collectTelemetry(e);
var telemetryInputs = form.querySelectorAll(
'input.vighnaghna-telemetry, input[name="vighnaghna_telemetry"], ' +
'input.botfence-telemetry, input[name="botfence_telemetry"], ' +
'input.kl-anti-spam-telemetry, input[name="kl_anti_spam_telemetry"]'
);
for (var i = 0; i < telemetryInputs.length; i++) {
telemetryInputs[i].value = telemetryVal;
}
}, true);
}
function scanAndProtectForms() {
var forms = document.querySelectorAll('form');
for (var i = 0; i < forms.length; i++) {
var f = forms[i];
var method = (f.getAttribute('method') || 'GET').toUpperCase();
if (
method === 'POST' ||
f.querySelector('.vighnaghna-token') ||
f.querySelector('.botfence-token') ||
f.querySelector('.kl-anti-spam-token') ||
f.classList.contains('wpcf7-form') ||
f.classList.contains('wpforms-form')
) {
attachFormSubmitHandler(f);
}
}
}
function refreshTokensForCachedPage() {
var tokenInputs = document.querySelectorAll(
'input.vighnaghna-token, input[name="vighnaghna_token"], ' +
'input.botfence-token, input[name="botfence_token"], ' +
'input.kl-anti-spam-token, input[name="kl_anti_spam_token"]'
);
if (tokenInputs.length === 0) return;
var requestUrl = config.restUrl + 'token';
var xhr = new XMLHttpRequest();
xhr.open('GET', requestUrl, true);
xhr.setRequestHeader('X-WP-Nonce', config.nonce || '');
xhr.onload = function() {
if (xhr.status >= 200 && xhr.status < 300) {
try {
var response = JSON.parse(xhr.responseText);
if (response && response.token) {
for (var j = 0; j < tokenInputs.length; j++) {
tokenInputs[j].value = response.token;
}
}
} catch (err) {
}
} else {
fallbackAjaxRefresh(tokenInputs);
}
};
xhr.onerror = function() {
fallbackAjaxRefresh(tokenInputs);
};
xhr.send();
}
function fallbackAjaxRefresh(tokenInputs) {
if (!config.ajaxUrl) return;
var xhr = new XMLHttpRequest();
xhr.open('POST', config.ajaxUrl, true);
xhr.setRequestHeader('Content-Type', 'application/x-www-form-urlencoded');
xhr.onload = function() {
if (xhr.status >= 200 && xhr.status < 300) {
try {
var response = JSON.parse(xhr.responseText);
if (response && response.success && response.data && response.data.token) {
for (var j = 0; j < tokenInputs.length; j++) {
tokenInputs[j].value = response.data.token;
}
}
} catch (e) {}
}
};
xhr.send('action=vighnaghna_refresh_token&nonce=' + encodeURIComponent(config.nonce || ''));
}
if (document.readyState === 'loading') {
document.addEventListener('DOMContentLoaded', function() {
scanAndProtectForms();
refreshTokensForCachedPage();
});
} else {
scanAndProtectForms();
refreshTokensForCachedPage();
}
if (window.MutationObserver) {
var observer = new MutationObserver(function(mutations) {
for (var m = 0; m < mutations.length; m++) {
var added = mutations[m].addedNodes;
for (var n = 0; n < added.length; n++) {
var node = added[n];
if (node.nodeType === 1) {
if (node.nodeName === 'FORM') {
attachFormSubmitHandler(node);
} else if (node.querySelectorAll) {
var nested = node.querySelectorAll('form');
for (var k = 0; k < nested.length; k++) {
attachFormSubmitHandler(nested[k]);
}
}
}
}
}
});
observer.observe(document.body || document.documentElement, {
childList: true,
subtree: true
});
}
window.Vighnaghna = {
refresh: refreshTokensForCachedPage,
protectForm: attachFormSubmitHandler,
getTelemetry: collectTelemetry
};
window.BotFence = window.Vighnaghna;
window.KLAntiSpam = window.Vighnaghna;
})();